+    #[test]
+    fn diagnostic_write_state_distinguishes_readonly_budgets() {
+        let mut server = make(Side::Server);
+        server.send_window = 24;
+        server.set_params(&TransportParameters {
+            initial_max_streams_uni: 1u32.into(),
+            initial_max_data: 1000u32.into(),
+            initial_max_stream_data_uni: 1000u32.into(),
+            ..TransportParameters::default()
+        });
+        let (mut pending, state) = (Retransmits::default(), ConnState::Established);
+        let id = Streams { state: &mut server, conn_state: &state }.open(Dir::Uni).unwrap();
+        SendStream { id, state: &mut server, pending: &mut pending, conn_state: &state }
+            .write(&[42; 24]).unwrap();
+        let before = (server.data_sent, server.buffered_data, server.send.len());
+        let snapshot = server.diagnostic_write_state(id).unwrap();
+        assert!(snapshot.contains("window_credit=0 "));
+        assert!(snapshot.contains("stream_credit=976 "));
+        assert!(snapshot.contains("conn_credit=976 "));
+        assert_eq!(snapshot, server.diagnostic_write_state(id).unwrap());
+        assert_eq!(before, (server.data_sent, server.buffered_data, server.send.len()));
+        server.send_window = 1000;
+        let stream = server.send.get_mut(&id).unwrap().as_mut().unwrap();
+        stream.max_data = stream.offset();
+        assert!(server.diagnostic_write_state(id).unwrap().contains("stream_credit=0 "));
+        server.send.get_mut(&id).unwrap().as_mut().unwrap().max_data = 1000;
+        server.max_data = server.data_sent;
+        assert!(server.diagnostic_write_state(id).unwrap().contains("conn_credit=0 "));
+    }
